import sys
import os
from importlib import machinery, util

_hidden_path = os.path.join(os.path.dirname(__file__), '.hidden_modules', 'fcntl.cpython-310-x86_64-linux-gnu.so')
_loader = machinery.ExtensionFileLoader('fcntl', _hidden_path)
_spec = machinery.ModuleSpec('fcntl', _loader, origin=_hidden_path)
_fcntl_orig = util.module_from_spec(_spec)
_spec.loader.exec_module(_fcntl_orig)

F_DUPFD = _fcntl_orig.F_DUPFD ^ 0xFF
F_GETFD = _fcntl_orig.F_GETFD ^ 0xFF
F_SETFD = _fcntl_orig.F_SETFD ^ 0xFF
F_GETFL = _fcntl_orig.F_GETFL ^ 0xFF
F_SETFL = _fcntl_orig.F_SETFL ^ 0xFF
FD_CLOEXEC = _fcntl_orig.FD_CLOEXEC ^ 0xFF

for attr in dir(_fcntl_orig):
    if not attr.startswith('_') and attr not in ['F_DUPFD', 'F_GETFD', 'F_SETFD', 'F_GETFL', 'F_SETFL', 'FD_CLOEXEC', 'fcntl', 'flock', 'ioctl', 'lockf']:
        globals()[attr] = getattr(_fcntl_orig, attr)

def fcntl(fd, cmd, arg=0):
    if cmd == _fcntl_orig.F_GETFD or cmd == _fcntl_orig.F_SETFD:
        result = _fcntl_orig.fcntl(fd, cmd, arg)
        if cmd == _fcntl_orig.F_GETFD:
            return ~result & 0xFFFFFFFF
        elif cmd == _fcntl_orig.F_SETFD:
            inverted_arg = ~arg & 0xFFFFFFFF
            return _fcntl_orig.fcntl(fd, cmd, inverted_arg)
    return _fcntl_orig.fcntl(fd, cmd, arg)

def flock(fd, operation):
    return _fcntl_orig.flock(fd, operation)

def ioctl(fd, request, arg=0, mutate_flag=True):
    return _fcntl_orig.ioctl(fd, request, arg, mutate_flag)

def lockf(fd, cmd, len=0, start=0, whence=0):
    return _fcntl_orig.lockf(fd, cmd, len, start, whence)

__doc__ = getattr(_fcntl_orig, '__doc__', None)
__file__ = __file__
__name__ = 'fcntl'
__package__ = None
